using CoracaoAnimal.Client;
using CoracaoAnimal.Core;
using System.Globalization;
namespace CoracaoAnimal.App;
public sealed class MainPage:ContentPage {
 static readonly Color Green=Color.FromArgb("#4A7C59"),Orange=Color.FromArgb("#E05C2A"),Brown=Color.FromArgb("#3D2B1F"),Beige=Color.FromArgb("#F7F3EE"),Muted=Color.FromArgb("#7A6355"),Line=Color.FromArgb("#E5D9CC"),Soft=Color.FromArgb("#EFE9E1");
 readonly ApiClient api=new(new Storage());readonly VerticalStackLayout body=new(){Spacing=14,Padding=new Thickness(18,22,18,32)};readonly Label state=new(){FontSize=12,Margin=new Thickness(18,8),TextColor=Color.FromArgb("#7A6355")};readonly ScrollView scroll;bool loaded;
 public MainPage(){Title="Coração Animal";BackgroundColor=Color.FromArgb("#F7F3EE");var brand=new Grid(){BackgroundColor=Color.FromArgb("#3D2B1F"),Padding=new Thickness(18,10),ColumnDefinitions={new ColumnDefinition(64),new ColumnDefinition(GridLength.Star)}};brand.Add(new Image(){Source="brand_logo.png",HeightRequest=54,WidthRequest=54,Aspect=Aspect.AspectFit},0,0);var brandText=new VerticalStackLayout(){Spacing=0,VerticalOptions=LayoutOptions.Center};brandText.Add(new Label(){Text="CORAÇÃO ANIMAL",TextColor=Colors.White,FontAttributes=FontAttributes.Bold,FontSize=20});brandText.Add(new Label(){Text="Adoção responsável transforma vidas",TextColor=Color.FromArgb("#F5C9B0"),FontSize=12});brand.Add(brandText,1,0);var menu=new HorizontalStackLayout(){Spacing=6,Padding=10,BackgroundColor=Colors.White};foreach(var item in new(string,Func<Task>)[]{("Animais",()=>Catalog()),("Para você",()=>Catalog(true)),("Adoções",Adoptions),("Doações",Donations),("Voluntariado",Volunteer),("Conta",Profile),("Entrar",Login)})menu.Add(Button(item.Item1,item.Item2,true));scroll=new ScrollView(){Content=body};var grid=new Grid(){RowDefinitions={new RowDefinition(GridLength.Auto),new RowDefinition(GridLength.Auto),new RowDefinition(GridLength.Star),new RowDefinition(GridLength.Auto)}};grid.Add(brand,0,0);grid.Add(new ScrollView(){Orientation=ScrollOrientation.Horizontal,Content=menu},0,1);grid.Add(scroll,0,2);grid.Add(state,0,3);Content=grid;}
 protected override async void OnAppearing(){base.OnAppearing();if(loaded)return;loaded=true;await Run(async()=>{await api.Initialize();await Catalog();});}
 Button Button(string text,Func<Task> work,bool secondary=false){var b=new Button(){Text=text,BackgroundColor=secondary?Colors.White:Green,TextColor=secondary?Brown:Colors.White,BorderColor=secondary?Line:Green,BorderWidth=1,CornerRadius=10,MinimumHeightRequest=48,FontAttributes=FontAttributes.Bold,Padding=new Thickness(18,10)};b.Clicked+=async(_,_)=>{b.IsEnabled=false;await Run(work);b.IsEnabled=true;};return b;}
 async Task Run(Func<Task> work){state.Text="Carregando…";try{await work();state.Text="Atualizado";}catch(Exception ex){state.Text="Operação não concluída";await DisplayAlertAsync("Coração Animal",ex.Message,"Entendi");}}
 void Page(string title){body.Clear();body.Add(new Label(){Text="CUIDAR • ACOLHER • CONECTAR",FontSize=11,CharacterSpacing=1.5,FontAttributes=FontAttributes.Bold,TextColor=Orange});body.Add(new Label(){Text=title,FontSize=31,FontFamily="serif",TextColor=Brown,Margin=new Thickness(0,0,0,8)});scroll.ScrollToAsync(0,0,false);}
 void Note(string text)=>body.Add(new Label(){Text=text,TextColor=Brown,FontSize=15,LineHeight=1.35});
 void Empty(string text)=>body.Add(new Border(){Stroke=Line,StrokeThickness=1,BackgroundColor=Colors.White,Padding=28,StrokeShape=new Microsoft.Maui.Controls.Shapes.RoundRectangle(){CornerRadius=16},Content=new Label(){Text=text,HorizontalTextAlignment=TextAlignment.Center,TextColor=Muted,FontSize=15}});
 Entry Field(string name,string value="",bool password=false,Keyboard? keyboard=null){body.Add(new Label(){Text=name,TextColor=Brown,FontSize=13,FontAttributes=FontAttributes.Bold,Margin=new Thickness(0,7,0,-7)});var e=new Entry(){Text=value,IsPassword=password,Keyboard=keyboard??Keyboard.Default,TextColor=Brown,BackgroundColor=Colors.White,MinimumHeightRequest=50,Placeholder=name};SemanticProperties.SetDescription(e,name);body.Add(new Border(){Stroke=Line,StrokeThickness=1,BackgroundColor=Colors.White,StrokeShape=new Microsoft.Maui.Controls.Shapes.RoundRectangle(){CornerRadius=10},Padding=new Thickness(10,0),Content=e});return e;}
 Picker Choice(string label,string[] items,string? selected=null){body.Add(new Label(){Text=label,TextColor=Brown,FontSize=13,FontAttributes=FontAttributes.Bold,Margin=new Thickness(0,7,0,-7)});var p=new Picker(){Title=label,ItemsSource=items,SelectedIndex=Math.Max(0,Array.IndexOf(items,selected)),TextColor=Brown,BackgroundColor=Colors.White,MinimumHeightRequest=50};body.Add(new Border(){Stroke=Line,StrokeThickness=1,BackgroundColor=Colors.White,StrokeShape=new Microsoft.Maui.Controls.Shapes.RoundRectangle(){CornerRadius=10},Padding=new Thickness(10,0),Content=p});return p;}
 CheckBox Check(string label){var c=new CheckBox(){Color=Color.FromArgb("#4A7C59")};SemanticProperties.SetDescription(c,label);body.Add(new HorizontalStackLayout(){Children={c,new Label(){Text=label,VerticalOptions=LayoutOptions.Center,MaximumWidthRequest=280,TextColor=Colors.Black}}});return c;}
 static string Value(Picker p)=>p.SelectedItem?.ToString()??"";
 void Action(string text,Func<Task> work)=>body.Add(Button(text,work));
 void AnimalCard(AnimalDto a){var content=new VerticalStackLayout(){Spacing=8,Padding=18};if(a.FotoUrl!=null)content.Add(new Image(){Source=new Uri(api.BaseUri!,a.FotoUrl).AbsoluteUri,HeightRequest=210,Aspect=Aspect.AspectFill,Margin=new Thickness(-18,-18,-18,8)});content.Add(new Label(){Text=a.Nome,FontFamily="serif",FontSize=27,TextColor=Brown});content.Add(new Label(){Text=$"{a.Especie} • {a.Idade} anos • {a.Porte}",FontSize=14,TextColor=Muted});if(a.Compatibilidade.HasValue)content.Add(new Label(){Text=$"Afinidade {a.Compatibilidade:0}%",FontAttributes=FontAttributes.Bold,TextColor=Orange});content.Add(Button("Conhecer "+a.Nome,()=>Details(a.Id)));body.Add(new Border(){Stroke=Line,StrokeThickness=1,BackgroundColor=Colors.White,StrokeShape=new Microsoft.Maui.Controls.Shapes.RoundRectangle(){CornerRadius=18},Content=content});}
 Task<bool> Confirm(string text)=>DisplayAlertAsync("Confirmar",text,"Sim","Não");
 AnimalDto Map(ApiAnimal a)=>new(a.IdAnimal,a.Nome,a.Especie,a.Raca,a.Idade,a.Porte,a.StatusAdocao,a.Descricao,a.FotoUrl);
 async Task<ApiAdotante?> CurrentAdopter(){var user=await api.Me()??throw new Exception("Entre para continuar.");return (await api.Get<List<ApiAdotante>>("api/Adotantes")??[]).FirstOrDefault(x=>x.Email.Equals(user.Email,StringComparison.OrdinalIgnoreCase));}
 Task Login(){Page("Bem-vindo de volta");var email=Field("E-mail",keyboard:Keyboard.Email);var senha=Field("Senha",password:true);Action("Entrar",async()=>{await api.Login(email.Text??"",senha.Text??"");await Profile();});Action("Criar conta",Register);return Task.CompletedTask;}
 Task Register(){Page("Criar conta");var nome=Field("Nome completo");var email=Field("E-mail",keyboard:Keyboard.Email);var senha=Field("Senha (mínimo 6 caracteres)",password:true);Action("Cadastrar",async()=>{await api.Register(nome.Text??"",email.Text??"",senha.Text??"");await Profile();});return Task.CompletedTask;}
 async Task Catalog(bool recommend=false,int page=1,string busca="",string especie="",string porte=""){var all=(await api.Get<List<ApiAnimal>>("api/Animais")??[]).Select(Map).Where(a=>(string.IsNullOrWhiteSpace(busca)||a.Nome.Contains(busca,StringComparison.OrdinalIgnoreCase))&&(string.IsNullOrWhiteSpace(especie)||a.Especie.Equals(especie,StringComparison.OrdinalIgnoreCase))&&(string.IsNullOrWhiteSpace(porte)||a.Porte.Equals(porte,StringComparison.OrdinalIgnoreCase))).ToList();if(recommend){var u=await api.Me()??throw new Exception("Entre para ver recomendações.");all=all.OrderByDescending(a=>a.Especie.Equals(u.EspeciePreferida,StringComparison.OrdinalIgnoreCase)).ToList();}var items=all.Skip((page-1)*12).Take(12).ToList();Page(recommend?"Companheiros para você":"Encontre um novo amigo");if(!recommend){Note("Conheça os animais que esperam por uma nova história.");var search=Field("Buscar pelo nome",busca);var sp=Choice("Espécie",["","Cachorro","Gato"],especie);var size=Choice("Porte",["","Pequeno","Médio","Grande"],porte);Action("Buscar animais",()=>Catalog(false,1,search.Text??"",Value(sp),Value(size)));}else Note("Sugestões organizadas para facilitar sua escolha.");foreach(var a in items)AnimalCard(a);if(items.Count==0)Empty("Nenhum animal encontrado com esses filtros.");if(page>1)Action("Página anterior",()=>Catalog(recommend,page-1,busca,especie,porte));if(page*12<all.Count)Action("Próxima página",()=>Catalog(recommend,page+1,busca,especie,porte));}
 async Task Details(int id){var a=Map(await api.Get<ApiAnimal>($"api/Animais/{id}")??throw new Exception("Animal não encontrado."));Page(a.Nome);if(a.FotoUrl!=null)body.Add(new Image(){Source=new Uri(api.BaseUri!,a.FotoUrl).AbsoluteUri,HeightRequest=260,Aspect=Aspect.AspectFit});Note($"{a.Especie} · {a.Raca} · {a.Idade} anos\n{a.Porte} · {a.Status}");Note(a.Descricao);if(a.Status.Contains("dispon",StringComparison.OrdinalIgnoreCase)){var obs=Field("Como você pretende acolher este animal?");var terms=Check("Entendo que a solicitação será avaliada pela equipe.");Action("Solicitar adoção",async()=>{if(!terms.IsChecked)throw new Exception("Confirme que entende o processo de avaliação.");var adotante=await CurrentAdopter()??throw new Exception("Complete e salve sua conta antes de solicitar a adoção.");await api.Post<ApiAdocao>("api/Adocoes",new ApiAdocaoInput(id,adotante.IdAdotante,"em_andamento",obs.Text??""));await Adoptions();});}}
 async Task Adoptions(){var adopter=await CurrentAdopter();List<ApiAdocao> items=adopter==null?[]:(await api.Get<List<ApiAdocao>>("api/Adocoes")??[]).Where(x=>x.IdAdotante==adopter.IdAdotante).ToList();Page("Minhas adoções");if(items.Count==0)Empty("Você ainda não solicitou uma adoção.");foreach(var a in items){var animal=a.Animal??await api.Get<ApiAnimal>($"api/Animais/{a.IdAnimal}");Note($"{animal?.Nome??"Animal"} · {a.Status}\n{a.DataAdocao.ToLocalTime():d} · {a.Observacoes}");if(!a.Status.Equals("concluida",StringComparison.OrdinalIgnoreCase))Action($"Cancelar solicitação #{a.IdAdocao}",async()=>{if(await Confirm("Cancelar esta solicitação?")){await api.Delete($"api/Adocoes/{a.IdAdocao}");await Adoptions();}});}}
 async Task Donations(){var adopter=await CurrentAdopter();List<ApiDoacao> items=adopter==null?[]:(await api.Get<List<ApiDoacao>>("api/Doacoes")??[]).Where(x=>x.IdAdotante==adopter.IdAdotante).ToList();Page("Ajude o acolhimento");Note("Registro de intenção de doação. Não realiza cobrança automática.");var valor=Field("Valor em reais",keyboard:Keyboard.Numeric);var forma=Choice("Forma de pagamento",["Pix","Transferência","Dinheiro"]);var desc=Field("Observação");Action("Registrar intenção",async()=>{var a=await CurrentAdopter()??throw new Exception("Complete e salve sua conta antes de registrar uma doação.");if(!decimal.TryParse(valor.Text,NumberStyles.Number,CultureInfo.GetCultureInfo("pt-BR"),out var v))throw new Exception("Informe um valor válido.");await api.Post<ApiDoacao>("api/Doacoes",new ApiDoacaoInput(a.IdAdotante,v,Value(forma),"Pendente",desc.Text??""));await Donations();});foreach(var d in items){Note($"#{d.IdDoacao} · R$ {d.Valor:N2} · {d.StatusPagamento}\n{d.FormaPagamento}");if(d.StatusPagamento.Equals("Pendente",StringComparison.OrdinalIgnoreCase))Action($"Cancelar doação #{d.IdDoacao}",async()=>{if(await Confirm("Cancelar esta intenção?")){await api.Delete($"api/Doacoes/{d.IdDoacao}");await Donations();}});}}
 async Task Volunteer(){var u=await api.Me()??throw new Exception("Entre para continuar.");var v=(await api.Get<List<ApiVoluntario>>("api/Voluntarios")??[]).FirstOrDefault(x=>x.Email.Equals(u.Email,StringComparison.OrdinalIgnoreCase));Page("Seja voluntário");Note(v==null?"Conte como você pode ajudar.":"Inscrição ativa desde "+v.DataInicio.ToLocalTime().ToString("d"));var tel=Field("Telefone",v?.Telefone??"",keyboard:Keyboard.Telephone);var area=Field("Área e disponibilidade",v?.AreaAtuacao??"");Action("Salvar inscrição",async()=>{var input=new ApiVoluntarioInput(u.Nome,u.Email,tel.Text??"",area.Text??"",DateTime.UtcNow);if(v==null)await api.Post<ApiVoluntario>("api/Voluntarios",input);else await api.Put<object>($"api/Voluntarios/{v.IdVoluntario}",input);await Volunteer();});if(v!=null)Action("Desativar inscrição",async()=>{if(await Confirm("Desativar sua inscrição?")){await api.Delete($"api/Voluntarios/{v.IdVoluntario}");await Volunteer();}});}
 async Task Profile(){var u=await api.Me()??throw new Exception("Entre para continuar.");var a=await CurrentAdopter();Page("Minha conta");Note(u.Email);var nome=Field("Nome completo",a?.NomeCompleto??u.Nome);var cpf=Field("CPF",a?.Cpf??"",keyboard:Keyboard.Numeric);var tel=Field("Telefone",a?.Telefone??"",keyboard:Keyboard.Telephone);var end=Field("Endereço",a?.Endereco??"");Action("Salvar perfil",async()=>{var input=new ApiAdotante(0,nome.Text??"",cpf.Text??"",u.Email,tel.Text??"",end.Text??"",DateTime.UtcNow);if(a==null)await api.Post<ApiAdotante>("api/Adotantes",input);else await api.Put<object>($"api/Adotantes/{a.IdAdotante}",input with {IdAdotante=a.IdAdotante,DataCadastro=a.DataCadastro});await Profile();});Action("Sair",async()=>{await api.Logout();await Login();});}
 Task Password(){Page("Alterar senha");var old=Field("Senha atual",password:true);var next=Field("Nova senha (mínimo 10 caracteres)",password:true);Action("Salvar nova senha",async()=>{await api.Put<object>("api/me/senha",new SenhaInput(old.Text??"",next.Text??""));await api.Forget();await Login();});return Task.CompletedTask;}
}
